files.content:
[hidden] { display: none !important; }

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
  color: #eaeaea;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  box-shadow: 8px 8px 0 #0f3460;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 4px;
  color: #e94560;
  letter-spacing: 1px;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b0;
  margin-bottom: 24px;
}

.field { margin-bottom: 20px; border: none; }

fieldset.field { padding: 0; }

label, legend {
  display: block;
  font-size: 1rem;
  margin-bottom: 8px;
  color: #c0c0d0;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 1.125rem;
  font-family: inherit;
  background: #0f3460;
  border: 3px solid #1a1a2e;
  color: #eaeaea;
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: #e94560;
  box-shadow: 0 0 0 3px #e94560;
}

.tip-buttons {
  display: flex;
  gap: 8px;
}

.tip-btn {
  flex: 1;
  padding: 12px 8px;
  font-size: 1rem;
  font-family: inherit;
  background: #0f3460;
  color: #eaeaea;
  border: 3px solid #1a1a2e;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
}

.tip-btn:hover {
  background: #1a4a7a;
}

.tip-btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: #e94560;
  color: #fff;
  border-color: #e94560;
}

.results {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 3px dashed #0f3460;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 12px;
  font-size: 1.125rem;
}

.result-row:last-child { margin-bottom: 0; }

.result-label { color: #a0a0b0; }

.result-value {
  font-weight: bold;
  color: #eaeaea;
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 1.5rem; }
  .tip-btn { padding: 10px 4px; font-size: 0.9375rem; }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = document.querySelectorAll('.tip-btn');
  var tipPerPersonEl = document.getElementById('tipPerPerson');
  var totalPerPersonEl = document.getElementById('totalPerPerson');

  var selectedTip = 15;

  function parseNumber(value, fallback) {
    var n = parseFloat(value);
    return isNaN(n) || n < 0 ? fallback : n;
  }

  function formatCurrency(amount) {
    return '$' + amount.toFixed(2);
  }

  function calculate() {
    var bill = parseNumber(billInput.value, 0);
    var people = parseNumber(peopleInput.value, 1);
    if (people < 1) people = 1;

    var tipTotal = bill * (selectedTip / 100);
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = (bill + tipTotal) / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function setSelectedTip(percent) {
    selectedTip = percent;
    tipButtons.forEach(function (btn) {
      var isActive = parseInt(btn.getAttribute('data-tip'), 10) === percent;
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setSelectedTip(parseInt(btn.getAttribute('data-tip'), 10));
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  calculate();
})();
